"use client";
/* Beep, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Beep(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("beep"); }, []);
  return React.createElement("piix-pal", { "pal": "beep", ...piixAttrs(props) });
}

export default Beep;
